<?php require "config/db.php";$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){$email=strtolower(trim($_POST["email"]??""));$pass=$_POST["password"]??"";$s=$pdo->prepare("SELECT * FROM users WHERE email=?");$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u["password"])){session_regenerate_id(true);$_SESSION["user"]=["id"=>$u["id"],"name"=>$u["name"],"email"=>$u["email"],"role"=>$u["role"]];header("Location: ".($u["role"]==="admin"?"admin.php":"index.php"));exit;}else{$error="Incorrect email or password.";}} ?>
